    const s_battery = new Battery()
    const upd_bar_1 = () => {
      const fill = Math.round(px(172) * Math.max(0, Math.min(1, s_battery.getCurrent() / 100)))
      bar_1.setProperty(ui.prop.MORE, { x: px(200) + 0, y: px(180), w: fill, h: px(14) })
    }
    s_battery.onChange(upd_bar_1)
    upd_bar_1()

